templates.react:
export function Mfa({
  heading = "{{heading}}",
  method = "{{method}}",
  maskedContact = "{{maskedContact}}",
  rememberDevice = {{rememberDevice}},
  accent = "{{accent}}",
}) {
  return (
    <form style={{ font: "14px/1.4 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", width: 300, padding: 20, borderRadius: 14, boxSizing: "border-box", border: "1px solid #24143018" }}>
      <h3 style={{ margin: "0 0 8px", fontSize: 16 }}>{heading}</h3>
      <p style={{ margin: "0 0 16px", fontSize: 13, color: "#24143099" }}>Using <strong>{method}</strong> &middot; {maskedContact}</p>
      <label style={{ display: "block", marginBottom: 12 }}>
        <span style={{ display: "block", marginBottom: 5, fontWeight: 600, fontSize: 13 }}>6-digit code</span>
        <input type="text" inputMode="numeric" autoComplete="one-time-code" pattern="[0-9]*" maxLength={6}
          style={{ width: "100%", boxSizing: "border-box", padding: 10, borderRadius: 8, border: "1.5px solid #24143030", font: "18px/1 system-ui, sans-serif", letterSpacing: ".3em" }} />
      </label>
      {rememberDevice && <label style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 13, marginBottom: 14 }}><input type="checkbox" defaultChecked />Remember this device for 30 days</label>}
      <button type="submit" style={{ width: "100%", padding: 10, borderRadius: 8, border: "none", background: accent, color: "#14351f", fontWeight: 700, cursor: "pointer" }}>Verify</button>
    </form>
  );
}
